def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    total = v1 + v2
    return {
        "value": total,
        "trace": {
            "v1": v1,
            "v2": v2,
            "operation": "sum",
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
